// --- Auth gate ---
// Set REQUIRE_AUTH = false ONLY while testing. Set the token below to match
// the value pasted into the dashboard's Settings box.
const REQUIRE_AUTH = true;
const SHARED_SECRET = 'REPLACE_WITH_YOUR_OWN_SECRET';

const headers = $input.first().json.headers || {};
const supplied = headers['x-agent-token'] || headers['X-Agent-Token'] || '';

if (REQUIRE_AUTH && supplied !== SHARED_SECRET) {
  return [{ json: { authFailed: true, botReply: 'Not authorised.' } }];
}

const body = $input.first().json.body || {};
const question = String(body.message || '').slice(0, 800);
const ctx = body.context || {};

// Build a compact, readable context block from what the dashboard sent
const topicLines = (ctx.topics || [])
  .map(t => `- ${t.name}: ${t.count} items today`).join('\n');

const itemLines = (ctx.topItems || []).map((it, i) =>
  `${i + 1}. "${it.headline}"\n   source: ${it.source} | platform: ${it.platform} | tone: ${it.sentiment} | score: ${it.score}${it.live ? ' | LIVE NEWS' : ' | demo item'}`
).join('\n');

const contextBlock = `You are answering a question from the Signal PR dashboard for YTL Creative Communications.
You are in READ-ONLY mode: never create, update, or log anything. Only answer.

TODAY'S TRACKED DATA
Total items today: ${ctx.itemsToday || 0}

Tracked topics:
${topicLines || '(none)'}

Top items in the feed right now:
${itemLines || '(none yet)'}

Answer the user's question using ONLY the data above. Be concise and practical — this is for a PR manager scanning quickly. If the data does not contain the answer, say so plainly rather than guessing. Do not invent headlines or sources.`;

return [{ json: {
  authFailed: false,
  question,
  systemContext: contextBlock,
  from: body.from || 'dashboard user'
} }];

const r = $input.first().json;

// Surface a real error instead of a silent generic message
if (r && (r.error || r.statusCode >= 400)) {
  const detail = r.error?.message || r.error || ('HTTP ' + r.statusCode);
  return [{ json: { botReply: 'ILMU call failed: ' + detail + '. Most likely the endpoint URL is wrong (try /v1/chat/completions) or the credential is not authorised.' } }];
}

let reply = r?.choices?.[0]?.message?.content
  || r?.content?.[0]?.text
  || r?.message?.content
  || r?.message
  || r?.reply
  || r?.output
  || '';

if (!reply || typeof reply !== 'string') {
  return [{ json: { botReply: 'ILMU returned an unrecognised response shape. Raw keys received: ' + Object.keys(r || {}).join(', ') + '. Check the Ask ILMU node URL and model.' } }];
}

return [{ json: { botReply: reply.trim() } }];
